{
  "tasks": [
    {
      "task_id": "T01",
      "title": "整体销售概况与规模",
      "business_question": "这份销售数据的总体订单数量、总销售额及平均单笔销售额是多少？",
      "priority": "P0",
      "priority_reason": "删除后无法回答“主要特征”中的基础量级问题，缺乏对数据整体规模的认知。",
      "requirement_ids": [
        "C01"
      ],
      "depends_on": [],
      "missing_inputs": [],
      "steps": [
        {
          "step_id": "S01_1",
          "operation": "aggregate",
          "params": {
            "metrics": [
              {
                "function": "count",
                "field": null,
                "alias": "total_orders"
              },
              {
                "function": "sum",
                "field": "field_0005",
                "alias": "total_sales_amount"
              },
              {
                "function": "avg",
                "field": "field_0005",
                "alias": "avg_sales_per_order"
              }
            ]
          }
        }
      ]
    },
    {
      "task_id": "T02",
      "title": "地区维度销售差异分析",
      "business_question": "不同地区的订单数量和销售额分布有何差异？哪个地区贡献最大？",
      "priority": "P0",
      "priority_reason": "探索“差异”的核心维度之一，通过分组聚合揭示地域结构特征。",
      "requirement_ids": [
        "C01"
      ],
      "depends_on": [],
      "missing_inputs": [],
      "steps": [
        {
          "step_id": "S02_1",
          "operation": "group_aggregate",
          "params": {
            "metrics": [
              {
                "function": "count",
                "field": null,
                "alias": "region_order_count"
              },
              {
                "function": "sum",
                "field": "field_0005",
                "alias": "region_sales_total"
              }
            ],
            "dimensions": [
              "field_0002"
            ]
          }
        },
        {
          "step_id": "S02_2",
          "operation": "sort",
          "params": {
            "field": "region_sales_total",
            "direction": "desc"
          }
        }
      ]
    },
    {
      "task_id": "T03",
      "title": "产品类别销售表现分析",
      "business_question": "不同产品类别的销售额和订单数分别是多少？哪类产品销售更强势？",
      "priority": "P0",
      "priority_reason": "探索“主要特征”中的业务结构，识别核心产品线的贡献度。",
      "requirement_ids": [
        "C01"
      ],
      "depends_on": [],
      "missing_inputs": [],
      "steps": [
        {
          "step_id": "S03_1",
          "operation": "group_aggregate",
          "params": {
            "metrics": [
              {
                "function": "count",
                "field": null,
                "alias": "category_order_count"
              },
              {
                "function": "sum",
                "field": "field_0005",
                "alias": "category_sales_total"
              }
            ],
            "dimensions": [
              "field_0007"
            ]
          }
        },
        {
          "step_id": "S03_2",
          "operation": "sort",
          "params": {
            "field": "category_sales_total",
            "direction": "desc"
          }
        }
      ]
    },
    {
      "task_id": "T04",
      "title": "时间趋势初步观察",
      "business_question": "按月份统计的销售总额变化趋势如何？是否存在明显的季节性或波动？",
      "priority": "P1",
      "priority_reason": "补充性分析，提供时间维度的视角以完善“主要特征”，但非唯一核心差异来源。",
      "requirement_ids": [
        "C01"
      ],
      "depends_on": [],
      "missing_inputs": [],
      "steps": [
        {
          "step_id": "S04_1",
          "operation": "derive",
          "params": {
            "function": "extract_month",
            "field": "field_0001",
            "alias": "order_month"
          }
        },
        {
          "step_id": "S04_2",
          "operation": "group_aggregate",
          "params": {
            "metrics": [
              {
                "function": "sum",
                "field": "field_0005",
                "alias": "monthly_sales_total"
              }
            ],
            "dimensions": [
              "order_month"
            ]
          }
        },
        {
          "step_id": "S04_3",
          "operation": "sort",
          "params": {
            "field": "order_month",
            "direction": "asc"
          }
        }
      ]
    }
  ]
}
